window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cdb07d2590f6fc9f"]={"versions": [{"id": "FIG-cdb07d2590f6fc9f", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des <em>BSW Module Description Templates</em> / BSWMD, AUTOSAR R3.0.7).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Modelliert die interne Verhaltensstruktur von Basissoftware-Modulen (<code>BswBehavior</code> als <code>ARElement</code>). Es bildet das formale Bindeglied zwischen statischem C-Quellcode (Funktionsrümpfe, kritische Zonen, Interrupts) und dem BSW-Scheduler (<code>SchM</code>), indem es Ausführungseinheiten, Scheduler-Events, Concurrency-Absicherungen und API-Einsprungpunkte formal spezifiziert.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Generalisierungen</p>\n<ul class=\"fig-list\">\n<li><strong><code>BswBehavior</code></strong> (<code>ARElement</code>): Wurzelcontainer für die Verhaltensbeschreibung eines BSW-Moduls.</li>\n<li><strong><code>BswModuleEntity</code></strong> (<code>ExecutableEntity</code>): Abstrakte Basisklasse aller ausführbaren Code-Einheiten eines Moduls.</li>\n<li><strong><code>BswSchedulableEntity</code></strong> ($\\Delta$ zu <code>BswModuleEntity</code>): Durch den BSW-Scheduler getaktete oder ereignisgesteuerte Funktion (z. B. zyklische <code>*_MainFunction()</code>).</li>\n<li><strong><code>BswInterruptEntity</code></strong> ($\\Delta$ zu <code>BswModuleEntity</code>): Behandlungsroutine für Hardware-Interrupts.</li>\n<li>Attribute: <code>interruptCategory: BswInterruptCategory</code>, <code>interruptSource: String</code>.</li>\n<li><strong><code>BswInterfaces::BswModuleEntry</code></strong> (<code>SwService</code>): Repräsentiert die konkrete C-Funktionssignatur / den Entry-Point.</li>\n<li>Attribute: <code>callType: BswCallType</code>, <code>executionContext: BswExecutionContext</code>, <code>isSynchronous: Boolean</code>, <code>serviceId: Int</code>.</li>\n<li><strong><code>InternalBehavior::ExclusiveArea</code></strong> (<code>Identifiable</code>): Kritischer Abschnitt zum gegenseitigen Ausschluss konkurrierender Zugriffe (Data Consistency).</li>\n<li><strong><code>BswEvent</code></strong> (<code>Identifiable</code>): Aktivierungsanforderung an den BSW-Scheduler (z. B. TimingEvent, DataReceivedEvent).</li>\n<li><strong><code>«enumeration» BswInterruptCategory</code></strong>: <code>cat1</code> (OS-umgehend, minimale Latenz), <code>cat2</code> (OS-managed Interrupt mit Scheduler-Awareness).</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>Kompositionen von <code>BswBehavior</code>:</strong></li>\n<li>$\\blacklozenge$ <code>+entity</code> $\\rightarrow$ <code>1..*</code> <code>BswModuleEntity</code> (Mindestens eine ausführbare Entität pro Verhalten).</li>\n<li>$\\blacklozenge$ <code>+exclusiveArea</code> $\\rightarrow$ <code>0..*</code> <code>ExclusiveArea</code> (Verwaltete kritische Abschnitte).</li>\n<li>$\\blacklozenge$ <code>+event</code> $\\rightarrow$ <code>0..*</code> <code>BswEvent</code> (Scheduler-Events zur Aktivierung).</li>\n<li><strong>Verbindungen von <code>BswModuleEntity</code>:</strong></li>\n<li><code>+implementedEntry</code> $\\rightarrow$ <code>1</code> <code>BswModuleEntry</code> (Exakt ein C-Funktionsr華mpf pro Entität).</li>\n<li><code>+calledEntry</code> $\\rightarrow$ <code>0..*</code> <code>BswModuleEntry</code> (Abhängigkeit zu aufgerufenen Fremd-/Untersystem-Funktionen).</li>\n<li><code>+canEnterExclusiveArea</code> $\\rightarrow$ <code>0..*</code> <code>ExclusiveArea</code> (Berechtigung zum Betreten definierter Schutzzonen).</li>\n<li><strong>Trigger-Beziehung:</strong></li>\n<li><code>BswEvent</code> $\\xrightarrow{\\text{+startsOnEvent}}$ <code>1</code> <code>BswSchedulableEntity</code> (Ein Event aktiviert genau eine schedulbare Entität).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Triggering (Scheduling):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das Laufzeitsystem / der <code>SchM</code> evaluiert ein konfiguriertes <code>BswEvent</code>.</li>\n<li>Bei Event-Eintritt triggert der Scheduler via <code>+startsOnEvent</code> die zugehörige <code>BswSchedulableEntity</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Funktionsaufruf & Verzweigung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Scheduler ruft den über <code>+implementedEntry</code> referenzierten C-Entry-Point synchron auf.</li>\n<li>Synchronous/Asynchronous Dispatch: Abhängig von <code>isSynchronous</code> und <code>callType</code> in <code>BswModuleEntry</code> werden Folgeaufrufe über <code>+calledEntry</code> blockierend oder nicht-blockierend abgesetzt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Interrupt-Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eintreffende ISRs aktivieren die <code>BswInterruptEntity</code>.</li>\n<li><code>cat1</code>: Direkte Ausführung im Hardware-Kontext ohne OS-API-Nutzung.</li>\n<li><code>cat2</code>: Ausführung im OS-Interrupt-Kontext mit voller SchM-/RTE-Integration.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Concurrency Guarding:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vor Betreten geschützter Abschnitte fordert die Entität via <code>+canEnterExclusiveArea</code> die Schutzinstanz an (<code>SchM_Enter_&lt;Mod&gt;_&lt;Area&gt;()</code>).</li>\n<li>Nach Abarbeitung erfolgt die Freigabe (<code>SchM_Exit_&lt;Mod&gt;_&lt;Area&gt;()</code>), um Prioritätsinversionen und Race Conditions zu vermeiden.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSWMD-Modellierung (ARXML):</strong></li>\n<li><code>entity</code> und <code>exclusiveArea</code> beschreiben <em>vorhandene Eigenschaften des C-Codes</em>.</li>\n<li><code>event</code> ist eine <em>Anforderung an den Integrator / BSW-Scheduler</em>, entsprechende Task-Bindings zu generieren.</li>\n<li><strong>Scheduler- & RTE-Generierung:</strong></li>\n<li>Fehlt die Zuordnung <code>BswEvent</code> $\\rightarrow$ <code>BswSchedulableEntity</code>, wird eine MainFunction im SchM nicht zyklisch aufgerufen.</li>\n<li>Jede Entität erfordert zwingend exakt einen deklarierten <code>implementedEntry</code> (Kardinalität <code>1</code>), welcher der exakten C-Funktionssignatur (<code>serviceId</code>, Header-Definition) entsprechen muss.</li>\n<li><strong>SchM-Sperrmechanismen:</strong></li>\n<li>Für jede via <code>+canEnterExclusiveArea</code> annotierte Zone generiert das Tooling modulspezifische Makros oder Inline-Funktionen (<code>SchM_Enter_<em></code> / <code>SchM_Exit_</em></code>). Der Treiber-Entwickler darf ausschließlich diese generierten Schnittstellen nutzen und keine manuellen OS-Interrupt-Sperren implementieren.</li>\n<li><strong>Interrupt-Klassifizierung:</strong></li>\n<li>Die Festlegung auf <code>cat1</code> verbietet jegliche Interaktion mit AUTOSAR-OS-Diensten innerhalb der ISR; Treiber für zeitkritische Peripherie (z. B. schnelle SPI-/Timer-Kanäle) müssen entsprechend auf atomare Hardware-Register-Operationen beschränkt werden.</li>\n</ul>"}, {"id": "FIG-2c677567b8f5fa85", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des <em>BSW Module Description Templates</em> / BSWMD, AUTOSAR R3.0.7).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Modelliert die interne Verhaltensstruktur von Basissoftware-Modulen (<code>BswBehavior</code> als <code>ARElement</code>). Es bildet das formale Bindeglied zwischen statischem C-Quellcode (Funktionsrümpfe, kritische Zonen, Interrupts) und dem BSW-Scheduler (<code>SchM</code>), indem es Ausführungseinheiten, Scheduler-Events, Concurrency-Absicherungen und API-Einsprungpunkte formal spezifiziert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Generalisierungen</p>\n<ul class=\"fig-list\">\n<li><strong><code>BswBehavior</code></strong> (<code>ARElement</code>): Wurzelcontainer für die Verhaltensbeschreibung eines BSW-Moduls.</li>\n<li><strong><code>BswModuleEntity</code></strong> (<code>ExecutableEntity</code>): Abstrakte Basisklasse aller ausführbaren Code-Einheiten eines Moduls.</li>\n<li><strong><code>BswSchedulableEntity</code></strong> ($\\Delta$ zu <code>BswModuleEntity</code>): Durch den BSW-Scheduler getaktete oder ereignisgesteuerte Funktion (z. B. zyklische <code>*_MainFunction()</code>).</li>\n<li><strong><code>BswInterruptEntity</code></strong> ($\\Delta$ zu <code>BswModuleEntity</code>): Behandlungsroutine für Hardware-Interrupts.</li>\n<li>Attribute: <code>interruptCategory: BswInterruptCategory</code>, <code>interruptSource: String</code>.</li>\n<li><strong><code>BswInterfaces::BswModuleEntry</code></strong> (<code>SwService</code>): Repräsentiert die konkrete C-Funktionssignatur / den Entry-Point.</li>\n<li>Attribute: <code>callType: BswCallType</code>, <code>executionContext: BswExecutionContext</code>, <code>isSynchronous: Boolean</code>, <code>serviceId: Int</code>.</li>\n<li><strong><code>InternalBehavior::ExclusiveArea</code></strong> (<code>Identifiable</code>): Kritischer Abschnitt zum gegenseitigen Ausschluss konkurrierender Zugriffe (Data Consistency).</li>\n<li><strong><code>BswEvent</code></strong> (<code>Identifiable</code>): Aktivierungsanforderung an den BSW-Scheduler (z. B. TimingEvent, DataReceivedEvent).</li>\n<li><strong><code>«enumeration» BswInterruptCategory</code></strong>: <code>cat1</code> (OS-umgehend, minimale Latenz), <code>cat2</code> (OS-managed Interrupt mit Scheduler-Awareness).</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>Kompositionen von <code>BswBehavior</code>:</strong></li>\n<li>$\\blacklozenge$ <code>+entity</code> $\\rightarrow$ <code>1..*</code> <code>BswModuleEntity</code> (Mindestens eine ausführbare Entität pro Verhalten).</li>\n<li>$\\blacklozenge$ <code>+exclusiveArea</code> $\\rightarrow$ <code>0..*</code> <code>ExclusiveArea</code> (Verwaltete kritische Abschnitte).</li>\n<li>$\\blacklozenge$ <code>+event</code> $\\rightarrow$ <code>0..*</code> <code>BswEvent</code> (Scheduler-Events zur Aktivierung).</li>\n<li><strong>Verbindungen von <code>BswModuleEntity</code>:</strong></li>\n<li><code>+implementedEntry</code> $\\rightarrow$ <code>1</code> <code>BswModuleEntry</code> (Exakt ein C-Funktionsr華mpf pro Entität).</li>\n<li><code>+calledEntry</code> $\\rightarrow$ <code>0..*</code> <code>BswModuleEntry</code> (Abhängigkeit zu aufgerufenen Fremd-/Untersystem-Funktionen).</li>\n<li><code>+canEnterExclusiveArea</code> $\\rightarrow$ <code>0..*</code> <code>ExclusiveArea</code> (Berechtigung zum Betreten definierter Schutzzonen).</li>\n<li><strong>Trigger-Beziehung:</strong></li>\n<li><code>BswEvent</code> $\\xrightarrow{\\text{+startsOnEvent}}$ <code>1</code> <code>BswSchedulableEntity</code> (Ein Event aktiviert genau eine schedulbare Entität).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Triggering (Scheduling):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das Laufzeitsystem / der <code>SchM</code> evaluiert ein konfiguriertes <code>BswEvent</code>.</li>\n<li>Bei Event-Eintritt triggert der Scheduler via <code>+startsOnEvent</code> die zugehörige <code>BswSchedulableEntity</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Funktionsaufruf & Verzweigung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Scheduler ruft den über <code>+implementedEntry</code> referenzierten C-Entry-Point synchron auf.</li>\n<li>Synchronous/Asynchronous Dispatch: Abhängig von <code>isSynchronous</code> und <code>callType</code> in <code>BswModuleEntry</code> werden Folgeaufrufe über <code>+calledEntry</code> blockierend oder nicht-blockierend abgesetzt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Interrupt-Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eintreffende ISRs aktivieren die <code>BswInterruptEntity</code>.</li>\n<li><code>cat1</code>: Direkte Ausführung im Hardware-Kontext ohne OS-API-Nutzung.</li>\n<li><code>cat2</code>: Ausführung im OS-Interrupt-Kontext mit voller SchM-/RTE-Integration.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Concurrency Guarding:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vor Betreten geschützter Abschnitte fordert die Entität via <code>+canEnterExclusiveArea</code> die Schutzinstanz an (<code>SchM_Enter_&lt;Mod&gt;_&lt;Area&gt;()</code>).</li>\n<li>Nach Abarbeitung erfolgt die Freigabe (<code>SchM_Exit_&lt;Mod&gt;_&lt;Area&gt;()</code>), um Prioritätsinversionen und Race Conditions zu vermeiden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSWMD-Modellierung (ARXML):</strong></li>\n<li><code>entity</code> und <code>exclusiveArea</code> beschreiben <em>vorhandene Eigenschaften des C-Codes</em>.</li>\n<li><code>event</code> ist eine <em>Anforderung an den Integrator / BSW-Scheduler</em>, entsprechende Task-Bindings zu generieren.</li>\n<li><strong>Scheduler- & RTE-Generierung:</strong></li>\n<li>Fehlt die Zuordnung <code>BswEvent</code> $\\rightarrow$ <code>BswSchedulableEntity</code>, wird eine MainFunction im SchM nicht zyklisch aufgerufen.</li>\n<li>Jede Entität erfordert zwingend exakt einen deklarierten <code>implementedEntry</code> (Kardinalität <code>1</code>), welcher der exakten C-Funktionssignatur (<code>serviceId</code>, Header-Definition) entsprechen muss.</li>\n<li><strong>SchM-Sperrmechanismen:</strong></li>\n<li>Für jede via <code>+canEnterExclusiveArea</code> annotierte Zone generiert das Tooling modulspezifische Makros oder Inline-Funktionen (<code>SchM_Enter_<em></code> / <code>SchM_Exit_</em></code>). Der Treiber-Entwickler darf ausschließlich diese generierten Schnittstellen nutzen und keine manuellen OS-Interrupt-Sperren implementieren.</li>\n<li><strong>Interrupt-Klassifizierung:</strong></li>\n<li>Die Festlegung auf <code>cat1</code> verbietet jegliche Interaktion mit AUTOSAR-OS-Diensten innerhalb der ISR; Treiber für zeitkritische Peripherie (z. B. schnelle SPI-/Timer-Kanäle) müssen entsprechend auf atomare Hardware-Register-Operationen beschränkt werden.</li>\n</ul>"}, {"id": "FIG-5d106d4887b12901", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des <em>BSW Module Description Templates</em> / BSWMD, AUTOSAR R3.0.7).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Modelliert die interne Verhaltensstruktur von Basissoftware-Modulen (<code>BswBehavior</code> als <code>ARElement</code>). Es bildet das formale Bindeglied zwischen statischem C-Quellcode (Funktionsrümpfe, kritische Zonen, Interrupts) und dem BSW-Scheduler (<code>SchM</code>), indem es Ausführungseinheiten, Scheduler-Events, Concurrency-Absicherungen und API-Einsprungpunkte formal spezifiziert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Generalisierungen</p>\n<ul class=\"fig-list\">\n<li><strong><code>BswBehavior</code></strong> (<code>ARElement</code>): Wurzelcontainer für die Verhaltensbeschreibung eines BSW-Moduls.</li>\n<li><strong><code>BswModuleEntity</code></strong> (<code>ExecutableEntity</code>): Abstrakte Basisklasse aller ausführbaren Code-Einheiten eines Moduls.</li>\n<li><strong><code>BswSchedulableEntity</code></strong> ($\\Delta$ zu <code>BswModuleEntity</code>): Durch den BSW-Scheduler getaktete oder ereignisgesteuerte Funktion (z. B. zyklische <code>*_MainFunction()</code>).</li>\n<li><strong><code>BswInterruptEntity</code></strong> ($\\Delta$ zu <code>BswModuleEntity</code>): Behandlungsroutine für Hardware-Interrupts.</li>\n<li>Attribute: <code>interruptCategory :BswInterruptCategory</code>, <code>interruptSource :String</code>.</li>\n<li><strong><code>BswInterfaces::BswModuleEntry</code></strong> (<code>SwService</code>): Repräsentiert die konkrete C-Funktionssignatur / den Entry-Point.</li>\n<li>Attribute: <code>callType :BswCallType</code>, <code>executionContext :BswExecutionContext</code>, <code>isSynchronous :Boolean</code>, <code>serviceId :Integer</code>.</li>\n<li><strong><code>InternalBehavior::ExclusiveArea</code></strong> (<code>Identifiable</code>): Kritischer Abschnitt zum gegenseitigen Ausschluss konkurrierender Zugriffe (Data Consistency).</li>\n<li><strong><code>BswEvent</code></strong> (<code>Identifiable</code>): Aktivierungsanforderung an den BSW-Scheduler (z. B. TimingEvent, DataReceivedEvent).</li>\n<li><strong><code>«enumeration» BswInterruptCategory</code></strong>: <code>cat1</code> (OS-umgehend, minimale Latenz), <code>cat2</code> (OS-managed Interrupt mit Scheduler-Awareness).</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>Kompositionen von <code>BswBehavior</code>:</strong></li>\n<li>$\\blacklozenge$ <code>+entity</code> $\\rightarrow$ <code>1..*</code> <code>BswModuleEntity</code> (Mindestens eine ausführbare Entität pro Verhalten).</li>\n<li>$\\blacklozenge$ <code>+exclusiveArea</code> $\\rightarrow$ <code>0..*</code> <code>ExclusiveArea</code> (Verwaltete kritische Abschnitte).</li>\n<li>$\\blacklozenge$ <code>+event</code> $\\rightarrow$ <code>0..*</code> <code>BswEvent</code> (Scheduler-Events zur Aktivierung).</li>\n<li><strong>Verbindungen von <code>BswModuleEntity</code>:</strong></li>\n<li><code>+implementedEntry</code> $\\rightarrow$ <code>1</code> <code>BswModuleEntry</code> (Exakt ein C-Funktionsrumpf pro Entität).</li>\n<li><code>+calledEntry</code> $\\rightarrow$ <code>0..*</code> <code>BswModuleEntry</code> (Abhängigkeit zu aufgerufenen Fremd-/Untersystem-Funktionen).</li>\n<li><code>+canEnterExclusiveArea</code> $\\rightarrow$ <code>0..*</code> <code>ExclusiveArea</code> (Berechtigung zum Betreten definierter Schutzzonen).</li>\n<li><strong>Trigger-Beziehung:</strong></li>\n<li><code>BswEvent</code> $\\xrightarrow{\\text{+startsOnEvent}}$ <code>1</code> <code>BswSchedulableEntity</code> (Ein Event aktiviert genau eine schedulbare Entität).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Triggering (Scheduling):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das Laufzeitsystem / der <code>SchM</code> evaluiert ein konfiguriertes <code>BswEvent</code>.</li>\n<li>Bei Event-Eintritt triggert der Scheduler via <code>+startsOnEvent</code> die zugehörige <code>BswSchedulableEntity</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Funktionsaufruf & Verzweigung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Scheduler ruft den über <code>+implementedEntry</code> referenzierten C-Entry-Point synchron auf.</li>\n<li>Synchronous/Asynchronous Dispatch: Abhängig von <code>isSynchronous</code> und <code>callType</code> in <code>BswModuleEntry</code> werden Folgeaufrufe über <code>+calledEntry</code> blockierend oder nicht-blockierend abgesetzt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Interrupt-Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eintreffende ISRs aktivieren die <code>BswInterruptEntity</code>.</li>\n<li><code>cat1</code>: Direkte Ausführung im Hardware-Kontext ohne OS-API-Nutzung.</li>\n<li><code>cat2</code>: Ausführung im OS-Interrupt-Kontext mit voller SchM-/RTE-Integration.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Concurrency Guarding:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vor Betreten geschützter Abschnitte fordert die Entität via <code>+canEnterExclusiveArea</code> die Schutzinstanz an (<code>SchM_Enter_&lt;Mod&gt;_&lt;Area&gt;()</code>).</li>\n<li>Nach Abarbeitung erfolgt die Freigabe (<code>SchM_Exit_&lt;Mod&gt;_&lt;Area&gt;()</code>), um Prioritätsinversionen und Race Conditions zu vermeiden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSWMD-Modellierung (ARXML):</strong></li>\n<li><code>entity</code> und <code>exclusiveArea</code> beschreiben <em>vorhandene Eigenschaften des C-Codes</em>.</li>\n<li><code>event</code> ist eine <em>Anforderung an den Integrator / BSW-Scheduler</em>, entsprechende Task-Bindings zu generieren.</li>\n<li><strong>Scheduler- & RTE-Generierung:</strong></li>\n<li>Fehlt die Zuordnung <code>BswEvent</code> $\\rightarrow$ <code>BswSchedulableEntity</code>, wird eine MainFunction im SchM nicht zyklisch aufgerufen.</li>\n<li>Jede Entität erfordert zwingend exakt einen deklarierten <code>implementedEntry</code> (Kardinalität <code>1</code>), welcher der exakten C-Funktionssignatur (<code>serviceId</code>, Header-Definition) entsprechen muss.</li>\n<li><strong>SchM-Sperrmechanismen:</strong></li>\n<li>Für jede via <code>+canEnterExclusiveArea</code> annotierte Zone generiert das Tooling modulspezifische Makros oder Inline-Funktionen (<code>SchM_Enter_<em></code> / <code>SchM_Exit_</em></code>). Der Treiber-Entwickler darf ausschließlich diese generierten Schnittstellen nutzen und keine manuellen OS-Interrupt-Sperren implementieren.</li>\n<li><strong>Interrupt-Klassifizierung:</strong></li>\n<li>Die Festlegung auf <code>cat1</code> verbietet jegliche Interaktion mit AUTOSAR-OS-Diensten innerhalb der ISR; Treiber für zeitkritische Peripherie (z. B. schnelle SPI-/Timer-Kanäle) müssen entsprechend auf atomare Hardware-Register-Operationen beschränkt werden.</li>\n</ul>"}], "trans": [{"from": "FIG-cdb07d2590f6fc9f", "to": "FIG-2c677567b8f5fa85", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2c677567b8f5fa85", "to": "FIG-5d106d4887b12901", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>BswInterfaces::BswModuleEntry</code>: Datentyp des Attributs <code>serviceId</code> von <code>Int</code> zu <code>Integer</code> geändert.</li>\n<li><code>BswInterfaces::BswModuleEntry</code> & <code>BswInterruptEntity</code>: Syntax der Attributdeklarationen redaktionell angepasst (Leerzeichen vor dem Doppelpunkt: <code>&lt;name&gt; :&lt;Typ&gt;</code> statt <code>&lt;name&gt;: &lt;Typ&gt;</code>).</li>\n</ul>"}]};
